-- Verified access details — batch 2: Alaska, Alberta, UK beats (2026-07-29)
UPDATE public.spots SET access = '{"shore": true, "boat": true, "ramp": "Public boat launches along the Sterling Highway corridor; drift and powerboat access is well developed", "parking": "Large paved and gravel car parks at Centennial, Swiftwater and Soldotna Creek parks", "walkIn": "Boardwalks and access stairs lead directly to the bank — about 200 m from the Soldotna Visitor Center car park", "facilities": ["Elevated fishing platforms", "Boardwalks and access stairs", "Toilets", "Campgrounds", "Visitor centre"], "notes": "Soldotna''s riverfront parks are purpose-built for bank fishing: roughly 10 boardwalks, 53 access stairways and several elevated platforms, some wheelchair accessible. Centennial Park alone has 25 sets of stairs and two 85-foot platforms. The Kenai River Special Management Area governs bank access to protect the riparian habitat — stay on the constructed walkways.", "sourceUrl": "https://dnr.alaska.gov/parks/aspunits/kenai/krsma.htm"}'::jsonb, updated_at = now() WHERE slug = 'kenai-river-salmon';
UPDATE public.spots SET access = '{"shore": true, "boat": true, "ramp": "Double boat ramp at Fish Creek Provincial Park (off Bow Bottom Trail SE); further ramps at Policeman''s Flats, McKinnon Flats, Legacy Island and Johnson Island", "parking": "Large car park at Fish Creek Provincial Park; gravel parking at the downstream access sites", "facilities": ["Boat ramps", "Toilets", "Picnic tables", "Rubbish bins"], "notes": "Access is managed under Alberta''s Bow River Access Plan. Fish Creek Provincial Park is open 8am-10pm in summer with the boat launch operating April to October, and day use is free. Legacy Island requires fording a channel to reach the ramp, which can be difficult in high water or winter ice. Policeman''s Flats is about 20 minutes south of Calgary via Highway 2 and Dumbow Road.", "sourceUrl": "https://open.alberta.ca/dataset/2d84767c-b4d6-4cf9-91e8-a0d3d66361b0/resource/cb11d013-e247-4c22-9ee3-dedb1251e48a/download/bow-river-access-plan.pdf"}'::jsonb, updated_at = now() WHERE slug = 'bow-river-alberta';
UPDATE public.spots SET access = '{"shore": true, "boat": false, "notes": "Almost the entire river is privately owned and fished in beats. Access is by day ticket, syndicate rod or hotel/lodge arrangement booked well in advance — there is effectively no free public access. Many beats are dry-fly-only and upstream-only, and some provide a ghillie.", "sourceUrl": "https://www.gov.uk/fishing-licences"}'::jsonb, updated_at = now() WHERE slug = 'river-test-hampshire';
UPDATE public.spots SET access = '{"shore": true, "boat": true, "notes": "Scotland issues no rod licence; instead you need permission from the beat owner or estate. Salmon permits come from the estate or the District Salmon Fishery Board, and popular autumn beats are booked months ahead. Some beats include a ghillie and boat. No salmon fishing on Sundays.", "sourceUrl": "https://www.gilledit.com/blog/fishing-permits-scotland-guide"}'::jsonb, updated_at = now() WHERE slug = 'river-tweed-scotland';
UPDATE public.spots SET access = '{"shore": true, "boat": false, "notes": "Fished in privately managed beats — a permit from the estate or association is required, and there is no general public right to fish. Many beats include ghillie support. No salmon fishing on Sundays.", "sourceUrl": "https://www.gilledit.com/blog/fishing-permits-scotland-guide"}'::jsonb, updated_at = now() WHERE slug = 'river-spey-scotland';
